import subprocess, os
def run(args, env_extra=None):
    env=dict(os.environ)
    env.pop('TERM',None)
    if env_extra:
        env.update(env_extra)
    r=subprocess.run(['./executable']+args, capture_output=True, env=env)
    return r

for args in [['--color','no','--help'], ['--color=no','--help'], ['--help','--color','no'], ['--color','yes','--help'], ['--color','auto','--help']]:
