    print(args, "len", len(r.stdout), "has_esc", has_esc, "exit", r.returncode, "stderr", r.stderr[:200])

for args in [['--color','no','--help'], ['--color=no','--help']]:
    env2={'TERM':'xterm'}
    r=run(args, env2)
    has_esc = b'\x1b' in r.stdout
    print(["TERM=xterm"]+args, "len", len(r.stdout), "has_esc", has_esc)

for env in [{'NO_COLOR':'1'}, {'CLICOLOR':'0'}]:
    r=run(['--help'], env)
    esc = b'\x1b' in r.stdout
    print("env", env, "len", len(r.stdout), "has_esc", esc)
PY"}

