import subprocess, os, re
def get_help(term, cols):
    env=dict(os.environ)
    env.pop('TERM',None)
    env.pop('COLUMNS',None)
    if term is not None:
        env['TERM']=term
    if cols is not None:
        env['COLUMNS']=cols
    r=subprocess.run(['./executable','--help'], capture_output=True, env=env)
    return r.stdout

for cols in ['40','80','100','120','200']:
    out=get_help('xterm', cols)
    # find table header line length stripped?
    ansi=re.compile(rb'\x1b\[[0-9;]*m')
    plain=ansi.sub(b'',out).decode(errors='replace')
    # find line with ┌
    for line in plain.split('\n'):
        if '┌' in line:
            print(f"COLS={cols} table header len chars={len(line)} bytes={len(line.encode())} line={line!r}")
            break
PY"}

