{"command": "python3 <<'PY'
import pty, os, subprocess, select, struct, fcntl, termios, re
def run_with_pty(width, term, cols_env):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, width, 0, 0))
    env=dict(os.environ)
    if term is None:
        env.pop('TERM',None)
    else:
        env['TERM']=term
    if cols_env is None:
        env.pop('COLUMNS',None)
    else:
        env['COLUMNS']=cols_env
    p = subprocess.Popen(['./executable','--help'], stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    out=b''
    while True:
        try:
            r,_,_=select.select([master],[],[],2)
            if not r:
                break
            data=os.read(master, 65536)
            if not data:
                break
            out+=data
        except OSError:
            break
    p.wait(timeout=5)
    os.close(master)
    return out

# pty width 80, COLUMNS=40, TERM=xterm -> which wins?
for (w, term, cols) in [(80,'xterm','40'), (40,'xterm','100'), (80,None,'100'), (80,None,None), (80,'unknownterm',None), (80,'unknownterm','100')]:
    out=run_with_pty(w, term, cols)
    ansi=re.compile(rb'\x1b\[[0-9;]*m')
    plain=ansi.sub(b'',out).decode(errors='replace')
    hdr=None
    for line in plain.splitlines():
        if '┌' in line:
            hdr=len(line.rstrip())
            break
    print(f"pty_w={w} TERM={term!r} COLUMNS={cols!r} -> header {hdr} len {len(out)}")
PY"}

