def is_term_known(term):
    if not term:
        return False
    for base in ['/usr/lib/terminfo','/usr/share/terminfo']:
        try:
            p = os.path.join(base, term[0], term)
            if os.path.exists(p):
                return True
        except:
            pass
    ti = os.environ.get('TERMINFO')
    if ti and term:
        try:
            if os.path.exists(os.path.join(ti, term[0], term)):
                return True
        except:
            pass
    return False

def parse_columns(s):
    # returns int or None if invalid
    # implements base-0 with leading spaces and + allowed, no trailing, 0 invalid
    if s is None:
        return None
    # lstrip leading whitespace (space, tab, etc.)
    t = s.lstrip(' \t\n\r\f\v')
    if t == '':
        return None
    # check for leading +/-
    if t[0] == '+':
        t2 = t[1:]
        if t2 == '':
            return None
    elif t[0] == '-':
        return None
    else:
        t2 = t
    # t2 must be non-empty and contain no whitespace
    if t2 == '':
        return None
    # check for trailing whitespace? Since we only lstripped, trailing remains in t2
    # if t2 contains any whitespace -> invalid
    for ch in t2:
        if ch in ' \t\n\r\f\v':
            return None
    # now parse base-0
    try:
        if t2.startswith('0x') or t2.startswith('0X'):
            if len(t2) <= 2:
                return None
            # hex digits
            for ch in t2[2:]:
                if ch not in '0123456789abcdefABCDEF':
                    return None
            v = int(t2, 16)
        elif len(t2) > 1 and t2[0] == '0':
            # octal
            for ch in t2:
                if ch not in '01234567':
                    return None
            v = int(t2, 8)
        else:
            # decimal
            for ch in t2:
                if ch not in '0123456789':
                    return None
            v = int(t2, 10)
    except:
        return None
    if v == 0:
        return None
    return v

def get_help_width():
    # if stdout is tty, use tty width
    try:
        if os.isatty(sys.stdout.fileno()):
            try:
                w = os.get_terminal_size(sys.stdout.fileno()).columns
                return w
            except:
                pass
    except:
        pass
    term = os.environ.get('TERM')
    known = is_term_known(term)
    if not known:
        return 50
    cols = os.environ.get('COLUMNS')
    if cols is not None:
        v = parse_columns(cols)
        if v is not None:
            return v
        else:
            return 80
    else:
        return 80

def apply_no_color(data: bytes) -> bytes:
    # replace color SGRs with \x1b[m, keep styles 1,3,4,0 and empty?
    # normal codes: 0,1,3,4,38;5;...,48;5;...,39,49
    # nocolor codes: '',0,1,3,4
    # So replace any SGR containing 38,48,39,49 with empty?
    # Need to parse \x1b[<params>m and replace if params contain color
    import re
    def repl(m):
        params = m.group(1).decode()
        # params like "48;5;235", "38;5;249", "49", "39", "38;5;239", "1", "3", etc.
        # Split by ; ?
        # If params == "" -> keep as \x1b[m (already nocolor)
        # If params contains 38 or 48 or ==39 or ==49 -> replace with ""
        # Actually need to handle combined? In help, codes are separate, not combined like "1;38;5;..."? Let's check: help has separate codes, not combined. But to be safe, if any of 38,48,39,49 present, replace whole with ""?
        # For install messages, codes are also separate.
        # So: if "38" in parts or "48" in parts or params=="39" or params=="49" -> return b"\x1b[m"
        # else keep original
        if params == "":
            return m.group(0)
        parts = params.split(";")
        # check for 38,48
        if "38" in parts or "48" in parts:
            return b"\x1b[m"
        if params in ("39","49"):
            return b"\x1b[m"
        # also check for 38;5 etc. already covered, but what about "38;5;13"? parts contains "38", so covered.
        return m.group(0)
    return re.sub(rb'\x1b\[([0-9;]*)m', repl, data)

