            for ch in t2[2:]:
                if ch not in '0123456789abcdefABCDEF':
                    return None
            v = int(t2, 16)
        elif len(t2) > 1 and t2[0] == '0':
            for ch in t2:
                if ch not in '01234567':
                    return None
            v = int(t2, 8)
        else:
            for ch in t2:
