def get_config_dir():
    xdg = os.environ.get('XDG_CONFIG_HOME')
    if xdg is not None and xdg != '':
        return os.path.join(xdg, 'broot')
    home = os.environ.get('HOME')
    if not home:
        try:
            home = os.path.expanduser('~')
        except:
            home = '/tmp'
        if not home or home == '~':
            home = '/tmp'
    return os.path.join(home, '.config', 'broot')

def get_data_dir():
    xdg = os.environ.get('XDG_DATA_HOME')
    if xdg is not None and xdg != '':
        return os.path.join(xdg, 'broot')
    home = os.environ.get('HOME')
    if not home:
        try:
            home = os.path.expanduser('~')
        except:
            home = '/tmp'
        if not home or home == '~':
            home = '/tmp'
    return os.path.join(home, '.local', 'share', 'broot')

