    # cap width for help rendering: max 110, min 1? For <1? width from get_help_width is >=1 or 50/80. For tty width, could be 0? os.get_terminal_size could return 0? Then help for 0? Our data has 1..110, for 0 fallback? But get_help_width for tty returns w as is, even if 0? Let's handle: if w<=0, use 80? Actually COLUMNS 0 fallback to 80, tty 0? Unlikely. We'll cap: if w<1, w=80? If w>110, w=110.
    # For testing, load from /tmp/capture_all
    if width > 110:
        width = 110
    if width < 1:
        width = 80
    try:
        # try embedded first? For now load from filesystem
        p = f'/tmp/capture_all/help_{width}.bin'
        if os.path.exists(p):
