                os.makedirs(os.path.dirname(dst) if os.path.dirname(dst) else p, exist_ok=True)
                # dst may be file in subdir? For conf.hjson, dirname is p, need makedirs p already done. For skins/..., need makedirs.
                if '/' in rel:
                    os.makedirs(os.path.join(p, os.path.dirname(rel)), exist_ok=True)
                with open(dst, 'wb') as f:
